const courses = [
  { title: "TypeScript Basics",    hours: 8,  level: "beginner",     published: true },
  { title: "React Patterns",       hours: 12, level: "intermediate", published: true },
  { title: "Node Internals",       hours: 16, level: "advanced",     published: false },
  { title: "CSS Layout Deep Dive", hours: 6,  level: "beginner",     published: true },
  { title: "Testing Web Apps",     hours: 10, level: "intermediate", published: true },
  { title: "Rust for JS Devs",     hours: 14, level: "advanced",     published: false },
];

// The loop way: traversal, filtering, math and accumulation in one knot
let total = 0;
for (let i = 0; i < courses.length; i++) {
  if (courses[i].published) {
    total += courses[i].hours;
  }
}
console.log(total); // 36

// The pipeline way: two named intents
const totalHours = courses
  .filter((c) => c.published)             // keep some
  .reduce((sum, c) => sum + c.hours, 0);  // collapse to one
console.log(totalHours); // 36

const titles = courses.map((c) => c.title);
console.log(titles);
// ["TypeScript Basics", "React Patterns", "Node Internals",
//  "CSS Layout Deep Dive", "Testing Web Apps", "Rust for JS Devs"]

const published = courses.filter((c) => c.published);
console.log(published.map((c) => c.title));
// ["TypeScript Basics", "React Patterns", "CSS Layout Deep Dive", "Testing Web Apps"]

// map never mutates the source — it builds a NEW array of the SAME length:
const doubled = courses.map((c) => ({ ...c, hours: c.hours * 2 }));
console.log(courses[0].hours); // 8  — untouched
console.log(doubled[0].hours); // 16 — only the copy changed

// Sum, with a seed (that trailing 0):
const totalHours = courses.reduce(
  (sum, c) => (c.published ? sum + c.hours : sum),
  0
);
console.log(totalHours); // 36

// Reduce can build ANY shape — group hours by level:
const byLevel = courses.reduce((acc, c) => {
  acc[c.level] = (acc[c.level] ?? 0) + c.hours;
  return acc;
}, {});
console.log(byLevel);
// { beginner: 14, intermediate: 22, advanced: 30 }

const advanced = courses.find((c) => c.level === "advanced");
console.log(advanced.title);                       // "Node Internals" — the FIRST match
console.log(courses.findIndex((c) => c.level === "advanced")); // 2
console.log(courses.find((c) => c.hours > 20));    // undefined — nothing matched

console.log(courses.some((c) => c.hours > 15));    // true — Node's 16 qualifies
console.log(courses.every((c) => c.hours > 5));    // true — the smallest is 6

// Short-circuit: the callback stops the moment the answer is known
const checked = [];
courses.some((c) => { checked.push(c.title); return c.hours > 15; });
console.log(checked);
// ["TypeScript Basics", "React Patterns", "Node Internals"] — and it stopped right there

const hours = [10, 9, 1];
console.log(hours.sort()); // [1, 10, 9]  ← not [1, 9, 10]!

// Trap 1: the default comparator sorts STRINGS. It converts every
// element with String(), then compares text: "1" < "10" < "9".

// Trap 2: sort() mutates the array AND returns the same reference:
console.log(hours.sort() === hours); // true — 'sorted' IS 'hours'

// The fix for both traps: pass a comparator, use the copying twin
const hours2 = [10, 9, 1];
const ascending = hours2.toSorted((a, b) => a - b); // numeric, non-mutating
console.log(ascending);           // [1, 9, 10]
console.log(hours2);              // [10, 9, 1] — untouched
console.log(hours2.toReversed()); // [1, 9, 10] — reversed copy

// Callback returns an ARRAY per element; flatMap flattens one level:
const publishedTitles = courses.flatMap((c) => (c.published ? [c.title] : []));
console.log(publishedTitles);
// ["TypeScript Basics", "React Patterns", "CSS Layout Deep Dive", "Testing Web Apps"]

// Returning [] is how flatMap drops elements; returning [a, b] expands them:
const oddSquares = [1, 2, 3].flatMap((n) => (n % 2 ? [n * n] : []));
console.log(oddSquares); // [1, 9] — evens dropped, odds squared

// Plain one-level flatten: map the identity
console.log([[1, 2], [3], []].flatMap((x) => x)); // [1, 2, 3]

// One expression, three stages, one answer:
const listing = courses
  .filter((c) => c.published)              // 4 courses
  .toSorted((a, b) => b.hours - a.hours)   // longest first
  .map((c) => `${c.title} (${c.hours}h)`); // human-readable labels

console.log(listing);
// ["React Patterns (12h)", "Testing Web Apps (10h)",
//  "TypeScript Basics (8h)", "CSS Layout Deep Dive (6h)"]

// When a chain misbehaves, name the stages and LOOK at them:
const published = courses.filter((c) => c.published);
console.log("after filter:", published.length); // 4

const sorted = published.toSorted((a, b) => b.hours - a.hours);
console.log("after sort:", sorted.map((c) => c.hours)); // [12, 10, 8, 6]

const listing = sorted.map((c) => `${c.title} (${c.hours}h)`);
console.log(listing[0]); // "React Patterns (12h)"

