const published = courses.filter((c) => c.published);

const listing = published
  .toSorted((a, b) => b.hours - a.hours)
  .map((c) => `${c.title} (${c.hours}h)`);

const totalHours = published.reduce((sum, c) => sum + c.hours, 0);
const averageHours = totalHours / published.length;

console.log(listing);      // ["React Patterns (12h)", "Testing Web Apps (10h)",
                           //  "TypeScript Basics (8h)", "CSS Layout Deep Dive (6h)"]
console.log(totalHours);   // 36
console.log(averageHours); // 9

// Sort before map: once a course becomes "React Patterns (12h)", its hours
// only exist inside a formatted string you'd have to parse back out.
// Each stage runs where its data still has the right shape.

